<?php// Inclusion du fichier contenant la connexion à la baserequire '../bdd/connexion.php';include('Receptionniste.php');include('headerRec.php');include('menu_Rec.php');include './Amelioration/reglage/recuperer_valeurs_reglages.php';/* calcul du nombre du jour */function NbJours($dte_a, $dte_now){    $tDeb = explode("-", $dte_a);    $tFin = explode("-", $dte_now);    $diff = mktime(0, 0, 0, $tFin[1], $tFin[2], $tFin[0]) -        mktime(0, 0, 0, $tDeb[1], $tDeb[2], $tDeb[0]);    return (($diff / 86400) + 1);}$tempsdujr = gmstrftime("%H:%M", time() + 3600);/* Fin calcul du nombre du jour */?><div id="page-wrapper" style="height:800px;" class="v_affiche">    <div class="col-lg-12">        <h3 class="page-header">Situation clients logés</h3>        <div class="panel panel-default">            <div class="panel-heading">                    <?php                    if ($_GET['cli'] == 'occ') { ?>                        <i class="fa fa-user"></i> Client Occasionnel                    <?php } else if(($_GET['cli'] == 'par') ){?>                        <h4><i class="fa fa-globe"></i> FACTURE GLOBALE</h4>                    <?php }?>            </div>            <!-- /.panel-heading -->            <div class="panel-body">                <?php if ($_GET['cli'] == 'par') {                    /* Recuperation infos partenaire */                    $requete_part = $bdd->prepare("SELECT * FROM t_responsable WHERE id_respo=:id_respo");                    $requete_part->BindParam(':id_respo',$_GET['part']);                    $requete_part->execute();                    while ($donnees = $requete_part->fetch()) {                        $nom = $donnees['nom_respo'];                        $entrep = $donnees['entreprise'];                        $tel = $donnees['telephone_respo'];                        $adr = $donnees['adresse_respo'];                    }                    /* Fin Recuperation */                    ?>                <div id="body-fact">                    <div class="row pad-top-botm client-info">                        <div class="col-lg-6 col-md-6 col-sm-6">                            <h4><strong>Informations Client</strong></h4>                            <strong>  <?php echo $nom; ?></strong>                            <br/>                            <b>Entreprise :</b> <?php echo $entrep; ?>                            <br/>                            <b>Adresse :</b> <?php echo $adr; ?>                            <br/>                            <b>Tél :</b> <?php echo $tel; ?>                            <br/>                           <!-- <b>E-mail :</b> info@clientdomain.com                            <br/>-->                            <b>Date d'édition :</b> <?php echo date('d/m/Y'); ?>                        </div>                        <div class="col-lg-6 col-md-6 col-sm-6">                           <!-- <h4><strong>Details Paiement</strong></h4>                            <b>Montant Facture : 990 USD </b>                            <br/>                            Date d'édition : 01th August 2014                            <br/>                            <b>Status paiement : Payé </b>                            <br/>                            Delivery Date : 10th August 2014                            <br/>                            Purchase Date : 30th July 2014-->                        </div>                    </div>                    <!--<div class="row">                        <div class="col-lg-12 col-md-12 col-sm-12">-->                    <div class="table-responsive">                        <table class="table table-striped table-bordered table-hover">                            <thead>                            <tr>                                <th>NO</th>                                <th>Chambre</th>                                <th>Client</th>                                <th>Accompagné(e)</th>                                <th>Tarif</th>                                <th>Nbr de jour</th>                                <th>Sous Total</th>                                <th>Action</th>                            </tr>                            </thead>                            <tbody>                            <?php                            $i = 1;                            $montant_tot_heb = 0;                            $montant_pay_heb = 0;                            $montant_heb_cl=0;                            $montant_tot_resto = 0;                            $montant_pay_resto = 0;                            $montant_resto_cl=0;                            //$som_paye = 0;                            //$som_reste = 0;                            /* Recuperation du paiement d'un client */                            $requete_paie = $bdd->prepare("SELECT a.id_client,a.nom_client,a.id_respo,b.id_res,b.num_reserv,b.remise,b.mont_par_chambre,b.dte_a,b.dte_s,c.id_ch,c.num_ch,c.tarif_ch,c.monnaie,d.id,d.mont_paye_heb,e.num_fact,e.id_fact, e.montant_total,f.montant_dollar AS montantUSD,f.montant_fc AS montantFC,b.type, g.id_respo AS respo_id,g.entreprise                            FROM t_client AS a,t_reservation AS b,t_chambre AS c, t_reserve_chambre AS d,t_facture AS e, t_reglement AS f, t_responsable AS g                             WHERE a.id_client=d.id_client                            AND b.id_res=d.idreserv                             AND e.res_ch_id=d.id                            AND c.id_ch=d.idchambre                            AND b.id_res=e.id_res                            AND e.id_fact=f.id_fact                             AND a.id_respo=g.id_respo                             AND d.statut='occupe'                             AND a.type_cl=:type_cl                            AND a.id_respo=:id_respo                             AND b.id_hotel=:id_hotel                            GROUP BY a.id_client                          ");                            /* Fin Recuperation */                            $type_cl='client partenaire';                            $requete_paie->BindParam(':type_cl',$type_cl);                            $requete_paie->BindParam(':id_respo',$_GET['part']);                            $requete_paie->BindParam(':id_hotel', $_SESSION['id_hotel']);                            $requete_paie->execute();                            while ($donnees = $requete_paie->fetch()) {                                ?>                                <?php                                $monnaie = 1;                                $montantUSD = $donnees['montantUSD'];                                $montantFC = $donnees['montantFC'];                                $montant_tot = $donnees['montant_total'];                                $num_fact = $donnees['num_fact'];                                $id_fact = $donnees['id_fact'];                                $id_client = $donnees['id_client'];                                $id_res_ch = $donnees['id'];                                $nom_client = $donnees['nom_client'];                                //recuperation accompagnateur de la chambre                                $requete_accomp= $bdd->prepare("SELECT rc.id_accomp,cl.nom_client                                FROM t_client AS cl,t_reserve_chambre AS rc                                WHERE cl.id_client=rc.id_accomp                                AND rc.statut='occupe'                                 AND rc.id_client=:id_client                                AND rc.id=:id                                ");                                $requete_accomp->BindParam(':id_client',$id_client);                                $requete_accomp->BindParam(':id',$id_res_ch);                                $requete_accomp->execute();                                //fin recuperation                                if($requete_accomp->rowCount()==0){                                    $id_accomp=NULL;                                    $nom_accomp='';                                }e