s;                                $nb_jr = $nb_jrs - 1;                                if ($nb_jr == 0) {                                    $nb_jr++;                                }                                $nbre_jr = $nb_jr;                                /* Fin Nombre de jour effectué*/                                /* Nombre de jour restant */                                $Nbj_rst = NbJours($dte_now, $dte_s);                                $nb_jrs_rst = $Nbj_rst;                                $nb_jr_rst = $nb_jrs_rst - 1;                                if ($nb_jr_rst == 0) {                                    $nb_jr_rst++;                                }                                $nbre_jr_rst = $nb_jr_rst;                                /* Fin Nombre de jour restant*/                                //CALCUL MONTANT PAYE HEB                                if ($m_affiche == 'USD') {                                    $montantFCUSD = round($montantFC * 1 / $tauxdollar, 2);                                    $montant_heb_cl =$montantUSD+$montantFCUSD;                                } else if ($m_affiche == 'CDF') {                                    $montantUSDFC = round($montantUSD*$tauxdollar, 2);                                    $montant_heb_cl =$montantFC+$montantUSDFC;                                }                                $montant_pay_heb +=$montant_heb_cl;                                //FIN                                $requete_resto = $bdd->prepare("SELECT c.id_fact,c.monnaie,c.mont_ttc_remise AS montant_resto,r.montant_dollar,r.montant_fc                                FROM t_reservation AS b, t_facture AS c,t_reglement AS r                                WHERE b.id_res=c.id_res                                AND b.id_hotel=:id_hotel                                 AND c.id_fact=r.id_fact                                AND b.type='commande'                                 AND b.chambr_id=:chambr_id                                 AND b.id_client=:client_id                                 ");                                $requete_resto->BindParam(':id_hotel', $_SESSION['id_hotel']);                                $requete_resto->BindParam(':chambr_id', $id_ch);                                $requete_resto->BindParam(':client_id', $id_client);                                $requete_resto->execute();                                $restaurant = $requete_resto->fetchAll(PDO::FETCH_OBJ);                                $montant_resto=0;                                $montant_resto_fc=0;                                $montant_resto_usd=0;                                $factmonnaie='';                                foreach ($restaurant as $resto) {                                    $factmonnaie = $resto->monnaie;                                    $montant_resto = $resto->montant_resto;                                    $montant_resto_fc = $resto->montant_fc;                                    $montant_resto_usd = $resto->montant_dollar;                                }                                //CALCUL MONTANT PAYE RESTO                                if ($factmonnaie == $m_affiche) {                                    $montant_resto = $montant_resto;                                } else {                                    if ($factmonnaie = 'USD' && $m_affiche == 'CDF') {                                        $montant_resto = round($montant_resto * $tauxdollar, 2);                                    } else {                                        $montant_resto = round($montant_resto * 1 / $tauxdollar, 2);                                    }                                }                                if ($m_affiche == 'USD') {                                    $montantFCUSD = round($montant_resto_fc * 1 / $tauxdollar, 2);                                    $montant_resto_cl =$montant_resto_usd+$montantFCUSD;                                } else if ($m_affiche == 'CDF') {                                    $montantUSDFC = round($montant_resto_usd*$tauxdollar, 2);                                    $montant_resto_cl =$montant_resto_fc+$montantUSDFC;                                }                                    $montant_pay_resto +=$montant_resto_cl;                                    $montant_tot_resto +=$montant_resto;                                //FIN                                //$montant_resto_usd = $montant_resto / $tauxdollar;                                //$montant_paye = $mont_paye_heb;                                ?>                                <tr>                                    <td><?php echo $i; ?></td>                                    <td><?php echo 'CH ' . $num_ch ; ?></td>                                    <td><?php echo $nom_client; ?></td>                                    <td><?php echo $nom_accomp; ?></td>                                    <td>                                        <?php                                        if ($chmonnaie == $m_affiche) {                                        $tarif_ch = $tarif_ch;                                        } else {                                        if ($chmonnaie = 'USD' && $m_affiche == 'CDF') {                                        $tarif_ch = round($tarif_ch * $tauxdollar, 2);                                        } else {                                        $tarif_ch = round($tarif_ch * 1 / $tauxdollar, 2);                                        }                                        }                                        echo $tarif_ch.' '.$m_affiche;                                        ?>                                    </td>                                    <td><?php echo $nbre_jr; ?></td>                                    <td>                                        <?php                                        $tarif_net = $tarif_ch * $nbre_jr;                                        //$montant_a_paye = $tarif_net - ($tarif_net * $remise_heb) / 100;                                        //$reste = $montant_a_paye - $montant_paye;                                         echo $tarif_net .' '.$m_affiche;                                        ?>                                    </td>                                    <td><a class="btn btn-info btn-xs details-cli" id="<?php echo $id_client; ?>" id1="<?php echo $id_res_ch; ?>" id2="<?php echo $id_ch; ?>">                                            <i class="fa fa-list"></i> Détails</a></td>                                </tr>                                <?php                                $montant_tot_heb += $tarif_net;                                //$som_paye += $montant_paye;                                //$som_reste += $reste;                                $i++;                            }                            /* Fin de la Recuperation du paiement d'un client */                            ?>                            </tbody>                        </table>                    </div>                    <hr/>                    <div class="ttl-amts">                        <h5> <b>Hébergement</b> : <?php echo $montant_tot_heb.' '.$m_affiche; ?></h5>                    </div>                    <hr/>                    <div class="ttl-amts">                        <h5> <b>Restauration</b> : <?php echo $montant_tot_resto.' '.$m_affiche; ?></h5>                    </div>                    <hr/>                    <div class="ttl-amts">                        <h5> <b>Montant Facture</b> : <?php echo $montant_tot_heb+$montant_tot_resto.' '.$m_affiche; ?></h5>                    </div>                    <hr/>                    <div class="ttl-amts">                        <h5> <b>Acompte</b> :<?php echo $montant_pay_heb+$montant_pay_resto.' '.$m_affiche; ?></h5>                    </div>                    <hr/>                    <div class="ttl-amts">                        <h5> <b>Status paiement</b> :                            <?php if ((($montant_tot_heb+$montant_tot_resto)-($montant_pay_heb+$montant_pay_resto))==0) {                            echo 'Payée';                            } else{                                echo 'En litige';                            }                            ?>                        </h5>                    </div>                    <hr/>                    <div class="ttl-amts">                        <h4><strong>Net à Payer : <?php echo ($montant_tot_heb+$montant_tot_resto)-($montant_pay_heb+$montant_pay_resto).' '.$m_affiche; ?></strong></h4>                    </div>                    <hr/>                    <!--</div>                </div>-->                    <div class="row pad-top-botm">                        <div class="col-lg-12 col-md-12 col-sm-12">                            <hr/>                            <a href="#" class="btn btn-primary" title="Imprimer"><i class="fa fa-print"></i> Imprimer</a>                            &nbsp;&nbsp;&nbsp;                <?php if ((($montant_tot_heb+$montant_tot_resto)-($montant_pay_heb+$montant_pay_resto))!=0) { ?>                            <a href="#" class="btn btn-success" data-toggle="modal" data-target=".bs-example-modal-lg" title="Payer"><i class="fa fa-money"></i> Payer</a>                <?php } ?>                        </div>                    </div>                </div>                <?php }else  if ($_GET['cli'] == 'occ') { ?>                <div class="table-responsive">                    <table class="table table-striped table-bordered table-hover" id="dataTables-example">                        <thead>                        <tr>                            <th>N°</th>                            <th>Client</th>                            <th>Chambre</th>                            <th>Tarif </th>                            <th>Nbr Jr eff</th>                            <th>Tarif net</th>                            <th>Action</th>              