;                            $num_fact = $donnees['num_fact'];                            $id_fact = $donnees['id_fact'];                            $id_client = $donnees['id_client'];                            $id_res_ch = $donnees['id'];                            $nom_client = $donnees['nom_client'];                            $id_respo = $donnees['id_respo'];                            $respo_id = $donnees['respo_id'];                            $id_res = $donnees['id_res'];                            $num_reserv = $donnees['num_reserv'];                            $mont_paye_heb = $donnees['mont_paye_heb'];                            $type = $donnees['type'];                            $id_ch = $donnees['id_ch'];                            $num_ch = $donnees['num_ch'];                            $tarif_ch = $donnees['tarif_ch'];                            $entreprise = $donnees['entreprise'];                            $remise_heb = $donnees['remise'];                            $mont_par_chambre = $donnees['mont_par_chambre'];                            $dte_a = $donnees['dte_a'];                            $dte_s = $donnees['dte_s'];                            date_default_timezone_set('Europe/Paris');                            $dte = date('H:i:s');                            $temps_actuel = $dte;                            if ($temps_actuel >= $temps_sortie) {                                $dte_now = date('Y-m-d', time() + 86400);                            } else {                                $dte_now = date('Y-m-d');                            }                            /* Nombre de jour effectué */                            $Nombres_jours = NbJours($dte_a, $dte_now);                            $nb_jrs = $Nombres_jours;                            $nb_jr = $nb_jrs - 1;                            if ($nb_jr == 0) {                                $nb_jr++;                            }                            $nbre_jr = $nb_jr;                            /* Fin Nombre de jour effectué*/                            /* Nombre de jour restant */                            $Nbj_rst = NbJours($dte_now, $dte_s);                            $nb_jrs_rst = $Nbj_rst;                            $nb_jr_rst = $nb_jrs_rst - 1;                            if ($nb_jr_rst == 0) {                                $nb_jr_rst++;                            }                            $nbre_jr_rst = $nb_jr_rst;                            /* Fin Nombre de jour restant*/                            $requete_resto = $bdd->prepare("SELECT SUM(mont_ttc_remise) AS montant_resto                                FROM t_reservation AS b, t_facture AS c                                WHERE b.id_res=c.id_res                                AND b.id_hotel=:id_hotel                                 AND b.type='commande'                                 AND b.etat_credit='credit'                                AND b.id_client=:client_id ");                            $requete_resto->BindParam(':id_hotel', $_SESSION['id_hotel']);                            $requete_resto->BindParam(':client_id', $id_client);                            $requete_resto->execute();                            $restaurant = $requete_resto->fetchAll(PDO::FETCH_OBJ);                            foreach ($restaurant as $resto) {                                $montant_resto = $resto->montant_resto;                            }                            $montant_resto_usd = $montant_resto / $tauxdollar;                            $montant_paye = $mont_paye_heb;                            ?>                            <?php                            $tarif_net = $tarif_ch * $nbre_jr;                            $montant_a_paye = $tarif_net - ($tarif_net * $remise_heb) / 100;                            $reste = $montant_a_paye - $montant_paye;                            ?>                            <tr>                                <td><?php echo $i; ?></td>                                <td><?php echo $nom_client; ?></td>                                <td><?php echo 'CH ' . $num_ch ; ?></td>                                <td><?php echo $tarif_ch. ' USD'; ?></td>                                <td><?php echo $nbre_jr; ?></td>                                <td><?php echo $tarif_net . ' USD'; ?></td>                                <?php                                if ($_GET['cli'] == 'par') { ?>                                <td>                                    <?php                                        echo $entreprise;                                    ?>                                </td>                                <?php } ?>                                <td><a class="btn btn-info btn-xs details-cli" id="<?php echo $id_client; ?>" id1="<?php echo $id_res_ch; ?>" id2="<?php echo $id_ch; ?>"><i                                            class="fa fa-list"></i> Détails</a></td>                            </tr>                            <?php                            $som_tot += $tarif_net;                            $som_paye += $montant_paye;                            $som_reste += $reste;                            $i++;                        }                        /* Fin de la Recuperation du paiement d'un client */                        ?>                        </tbody>                        </tfoot>         <!--               <tr style="color:#ff1b2d;">                            <td colspan="5"></td>                            <td><?php /*echo $som_tot . '$'; */?></td>                            <td><?php /*echo $som_paye . '$'; */?></td>                            <td colspan="4"></td>                        </tr>-->                        </tfoot>                    </table>                </div>                <?php }?>                <!-- /.panel-body -->            </div>            <!-- /.panel -->        </div>        <!-- /.col-lg-12 -->    </div>    <!-- /.row --></div><!-- /#page-wrapper --></div