ils-cli').click(function (e) {            var client_id = $(this).attr("id");            var fact = $(this).attr("id1");            var idch = $(this).attr("id2");            location.href = "classeur.php?client_id=" + client_id+"&fact="+fact+"&idch="+idch;        });    });</script>